function AdminRisk({ violations, onUpdate }) { return <><PageHeader eyebrow="TRUST & SAFETY" title="Risk & abuse" description="Review cross-platform trading alerts, duplicate accounts, and suspicious activity."/><div className="rule-metrics"><Metric label="Open cases" value={violations.filter(v=>v.status==='Needs review').length} change="Awaiting investigation" icon={ShieldAlert}/><Metric label="Resolved cases" value={violations.filter(v=>v.status==='Resolved').length} change="Cases closed" icon={CheckCircle2}/><Metric label="Detection categories" value="08" change="Rule and fraud signals" icon={Flag}/></div><div className="panel table-panel"><SectionTitle eyebrow="INVESTIGATION QUEUE" title="Recent cases"/><TableWrap><thead><tr><th>TRADER</th><th>BROKER</th><th>SIGNAL</th><th>SEVERITY</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{violations.map(v=><tr key={v.id}><td><strong>{v.trader}</strong><small className="subline">{v.account}</small></td><td>Northstar Markets</td><td>{v.rule}<small className="subline">{v.detail}</small></td><td><Badge tone={v.severity==='High'?'red':v.severity==='Medium'?'amber':'neutral'}>{v.severity}</Badge></td><td><Status value={v.status}/></td><td><select className="action-select" value={v.status} onChange={e=>onUpdate(v.id,e.target.value)} aria-label={`Review ${v.trader}`}><option>Needs review</option><option>Resolved</option><option>Disqualified</option></select></td></tr>)}</tbody></TableWrap></div><div className="panel detail-panel"><SectionTitle eyebrow="DETECTION COVERAGE" title="Signals under review"/><div className="trigger-grid">{['Duplicate registrations','Multiple competition accounts','Abnormal performance','Restricted instruments','Rule manipulation','Coordinated activity','Unauthorized trading','Daily loss breaches'].map(x=><span key={x}><ShieldAlert size={16}/>{x}</span>)}</div></div></> }
function AdminUsers() { const rows=[['Morgan Lee','Platform admin','All brokers','Active'],['Jordan Davis','Broker admin','Northstar Markets','Active'],['Avery Kim','Competition manager','Northstar Markets','Active'],['Taylor Reed','Support manager','All brokers','Active'],['Riley Park','Sales manager','Atlas FX','Pending']]; return <><PageHeader eyebrow="IDENTITY & ACCESS" title="Users & roles" description="Review platform and broker staff access by scope."/><div className="panel table-panel"><SectionTitle eyebrow="STAFF DIRECTORY" title="Access assignments"/><TableWrap><thead><tr><th>USER</th><th>ROLE</th><th>ACCESS SCOPE</th><th>STATUS</th></tr></thead><tbody>{rows.map(([name,role,scope,status])=><tr key={name}><td><strong>{name}</strong></td><td>{role}</td><td>{scope}</td><td><Status value={status}/></td></tr>)}</tbody></TableWrap></div><div className="two-columns"><div className="panel detail-panel"><SectionTitle eyebrow="PERMISSIONS" title="Role boundaries"/><div className="signal-list">{[['Platform admin','Cross-broker operations and configuration'],['Broker admin','Own competitions, traders, analytics, and prizes'],['Competition manager','Competition setup and event operations'],['Sales manager','Trader leads and profiles'],['Support manager','Participant cases and support']].map(([name,detail])=><div key={name}><Shield size={17}/><span><strong>{name}</strong><small>{detail}</small></span></div>)}</div></div><div className="panel detail-panel"><SectionTitle eyebrow="POLICY" title="Access safeguards"/><p className="muted">Staff permissions should be enforced by the backend for every API request. The role sign-in here demonstrates interface boundaries only.</p><div className="notice"><LockKeyhole size={18}/> Production access requires authentication, organization scoping, session management, and audit logging.</div></div></div></> }
function AdminAudit() { const [query,setQuery]=useState(''); const rows=[['Morgan Lee','Broker status reviewed','Horizon Trading','Oct 10, 09:18'],['Jordan Davis','Competition published','Apex Trader Challenge','Oct 09, 11:42'],['Taylor Reed','Rule case reviewed','Oliver Grant','Oct 09, 10:17'],['Jordan Davis','Participant approved','Alex Morgan','Oct 08, 15:18'],['Morgan Lee','Role assignment changed','Avery Kim','Oct 07, 16:02']].filter(r=>r.join(' ').toLowerCase().includes(query.toLowerCase())); return <><PageHeader eyebrow="ACCOUNTABILITY" title="Audit logs" description="Trace important administrative decisions and changes."/><div className="panel table-panel"><div className="panel-heading"><div><span className="eyebrow">RECENT ACTIVITY</span><h2>Event history</h2></div><div className="search-field compact"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search events..."/></div></div><TableWrap><thead><tr><th>ACTOR</th><th>ACTION</th><th>OBJECT</th><th>WHEN</th></tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{v}</td>)}</tr>)}</tbody></TableWrap>{!rows.length&&<Empty title="No events found" text="Try a different search."/>}</div><div className="notice"><BookOpen size={18}/> These events are illustrative. Production logs should include previous and new values, user, timestamp, object, and device or IP where appropriate.</div></> }
function AdminSupport() { const [tickets,setTickets]=useState([['SUP-1042','Northstar Markets','Leaderboard calculation question','Open'],['SUP-1041','Alex Morgan','Competition eligibility review','Open'],['SUP-1038','Atlas FX','MT5 sync assistance','Resolved']]); const resolve=id=>setTickets(items=>items.map(t=>t[0]===id?[...t.slice(0,3),'Resolved']:t)); return <><PageHeader eyebrow="PLATFORM SUPPORT" title="Support queue" description="Handle broker and trader escalations in one place."/><div className="summary-strip"><div><LifeBuoy size={19}/><strong>{tickets.length}</strong><span>Total tickets</span></div><div><Clock3 size={19}/><strong>{tickets.filter(t=>t[3]==='Open').length}</strong><span>Open</span></div><div><CheckCircle2 size={19}/><strong>{tickets.filter(t=>t[3]==='Resolved').length}</strong><span>Resolved</span></div><div><Shield size={19}/><strong>0</strong><span>Critical</span></div></div><div className="panel table-panel"><SectionTitle eyebrow="CASE QUEUE" title="Recent requests"/><TableWrap><thead><tr><th>ID</th><th>REQUESTER</th><th>SUBJECT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{tickets.map(([id,requester,subject,status])=><tr key={id}><td><strong>{id}</strong></td><td>{requester}</td><td>{subject}</td><td><Status value={status}/></td><td><button className="text-link" disabled={status==='Resolved'} onClick={()=>resolve(id)}>{status==='Resolved'?'Closed':'Mark resolved'} <Check size={14}/></button></td></tr>)}</tbody></TableWrap></div></> }
function AdminSettings() { return <><PageHeader eyebrow="PLATFORM CONFIGURATION" title="Configuration" description="Review global competition, scoring, and security defaults."/><div className="two-columns"><div className="panel detail-panel"><SectionTitle eyebrow="COMPETITION DEFAULTS" title="Available formats"/><div className="trigger-grid two-up">{['Demo','Live account','Combined','Daily / weekly / monthly','Flash','Regional','Private','Multi-stage'].map(x=><span key={x}><CheckCircle2 size={16}/>{x}</span>)}</div></div><div className="panel detail-panel"><SectionTitle eyebrow="SCORING OPTIONS" title="Ranking methods"/><div className="trigger-grid two-up">{['P&L %','Absolute P&L','Equity growth','Balance growth','Trading volume','Win rate','Risk-adjusted','Custom scoring'].map(x=><span key={x}><TrendingUp size={16}/>{x}</span>)}</div></div></div><div className="notice"><Settings2 size={18}/> The final enabled formats, rankings, and global policies still need client confirmation.</div></> }

